 private int origin(World world)throws Exception{Class<?> layout=Class.forName("tr.kasabatr.vampir.MapLayout",true,game.getClass().getClassLoader());Method method=layout.getDeclaredMethod("originX",String.class);method.setAccessible(true);return (Integer)method.invoke(null,world.getName());}
 private Object field(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
 private void set(Object o,String name,Object value)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}
 private Object call(Object o,String name,Object... args)throws Exception{Method m=Arrays.stream(o.getClass().getDeclaredMethods()).filter(x->x.getName().equals(name)&&x.getParameterCount()==args.length).findFirst().orElseThrow();m.setAccessible(true);return m.invoke(o,args);}
 private Object room(Player p)throws Exception{return ((Map<?,?>)field(game,"membership")).get(p.getUniqueId());}
 private void state(Player p)throws Exception{Map<String,Object>d=new LinkedHashMap<>();d.put("uuid",p.getUniqueId().toString());d.put("entity",p.getEntityId());d.put("held",p.getInventory().getHeldItemSlot());d.put("world",p.getWorld().getName());d.put("mode",p.getGameMode().name());d.put("x",p.getX());d.put("y",p.getY());d.put("z",p.getZ());d.put("items",Arrays.stream(p.getInventory().getContents()).filter(Objects::nonNull).map(i->i.getType()+":"+i.getAmount()).toList());d.put("cursor",p.getItemOnCursor().getType()+":"+p.getItemOnCursor().getAmount());d.put("absorption",p.getAbsorptionAmount());d.put("level",p.getLevel());d.put("effects",p.getActivePotionEffects().stream().map(e->e.getType().getKey().getKey()).toList());d.put("backup",new java.io.File(game.getDataFolder(),"recoveries/"+p.getUniqueId()+".yml").isFile());d.put("active",((Set<?>)field(game,"lobby")).contains(p.getUniqueId()));d.put("roomCount",((Map<?,?>)field(game,"rooms")).size());Object r=room(p);if(r!=null){d.put("room",field(r,"id"));d.put("phase",field(r,"phase").toString());d.put("demo",field(r,"demo"));d.put("members",((Set<?>)field(r,"members")).size());d.put("alive",((Set<?>)field(r,"alive")).contains(p.getUniqueId()));d.put("aliveCount",((Set<?>)field(r,"alive")).size());d.put("role",String.valueOf(((Map<?,?>)field(r,"roles")).get(p.getUniqueId())));d.put("shots",((Map<?,?>)field(r,"hunterShots")).get(p.getUniqueId()));d.put("taskDone",field(r,"taskDone"));d.put("fakeTaskDone",field(r,"fakeTaskDone"));d.put("taskGoal",field(r,"taskGoal"));d.put("huntRemaining",call(r,"dayKillRemainingMillis",p.getUniqueId()));d.put("firstNightDone",field(r,"firstNightDone"));List<Map<String,Object>> tasks=new ArrayList<>();for(Object t:((Map<?,?>)field(r,"tasks")).getOrDefault(p.getUniqueId(),null)==null?List.of():(List<?>)((Map<?,?>)field(r,"tasks")).get(p.getUniqueId()))tasks.add(taskState(t));d.put("tasks",tasks);Object common=((Map<?,?>)field(r,"commonWork")).get(p.getUniqueId());if(common!=null)d.put("common",taskState(common));d.put("speaker",call(r,"isSpeaker",p.getUniqueId()));d.put("seconds",field(r,"seconds"));d.put("dayRemaining",field(r,"dayRemaining"));org.bukkit.boss.BossBar bar=(org.bukkit.boss.BossBar)field(r,"bar");d.put("barTitle",bar.getTitle());d.put("barProgress",bar.getProgress());Object guide=field(r,"guide");if(guide!=null){org.bukkit.boss.BossBar role=(org.bukkit.boss.BossBar)((Map<?,?>)field(guide,"roleBars")).get(p.getUniqueId());if(role!=null){d.put("roleTitle",role.getTitle());d.put("roleViewers",role.getPlayers().stream().map(Player::getName).toList());}d.put("mapId",((org.bukkit.map.MapView)field(guide,"map")).getId());}}say(p,"state:"+json.toJson(d));}
 private Map<String,Object> taskState(Object task)throws Exception{Map<String,Object> d=new LinkedHashMap<>();for(String name:List.of("station","kind","completed","carrying","leg","maintenance"))d.put(name,field(task,name));d.put("destination",call(task,"destination"));Object work=field(task,"work");Map<String,Object> w=new LinkedHashMap<>();for(String name:List.of("step","round","startedAt","nextInputAt","preview","done","sequence"))w.put(name,field(work,name));w.put("labels",call(work,"labels"));w.put("minimumMillis",call(work,"minimumMillis"));d.put("step",field(work,"step"));d.put("work",w);return d;}
 private void say(Player p,String text){p.sendMessage(net.kyori.adventure.text.Component.text("vampir-probe:"+text));}
